import Foundation

/// Why `decode(json:)` failed: the bytes are not the expected JSON shape, or the values break the rules.
public enum JSONFailure<F: Error>: Error {
    case malformed(DecodingError)
    case invalid(Issues<F>)
}

/// A `Parsable` whose raw input is `Codable`. Conformance is generated by `@JSONSchema`.
public protocol JSONParsable: Parsable where Input: Codable {}

extension JSONParsable {
    public static func decode(json: Data) -> Result<Self, JSONFailure<Failure>> {
        let input: Input
        do { input = try JSONDecoder().decode(Input.self, from: json) } catch {
            // ponytail: JSONDecoder documents DecodingError as its only error for Decodable inputs.
            return .failure(.malformed(error as! DecodingError))
        }
        return parse(input).mapError(JSONFailure.invalid)
    }

    /// Sorted keys, so equal values give equal bytes.
    public func json() throws(EncodingError) -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        do { return try encoder.encode(encoded) } catch { throw error as! EncodingError }
    }
}
